from google.cloud import texttospeech


def select_voice(language_code="en-US", gender=None):
    client = texttospeech.TextToSpeechClient()
    voices = client.list_voices(language_code=language_code).voices

    selected_voices = []
    for voice in voices:
        if gender is None or texttospeech.SsmlVoiceGender(gender).name == voice.ssml_gender.name:
            selected_voices.append({
                "name": voice.name,
                "language_codes": voice.language_codes,
                "ssml_gender": voice.ssml_gender.name,
                "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
            })
    return {"voices": selected_voices}

import os

def save_audio(audio_bytes, file_path, content_type="audio/mpeg"):
    # Determine file extension based on content_type
    if "mpeg" in content_type or "mp3" in content_type:
        extension = ".mp3"
    elif "wav" in content_type:
        extension = ".wav"
    else:
        extension = ".bin" # Default to binary if unknown

    # Ensure the file_path has the correct extension
    if not file_path.endswith(extension):
        file_path = file_path + extension

    with open(file_path, "wb") as out:
        out.write(audio_bytes)
    return {"file_path": os.path.abspath(file_path), "size": len(audio_bytes)}

from google.cloud import texttospeech

def get_text_to_speech_client():
    """Returns a Google Cloud Text-to-Speech client."""
    return texttospeech.TextToSpeechClient()

def get_audio_config(encoding="MP3", speaking_rate=1.0, pitch=0.0):
    """Returns a configured AudioConfig object."""
    return texttospeech.AudioConfig(
        audio_encoding=getattr(texttospeech.AudioEncoding, encoding.upper()),
        speaking_rate=speaking_rate,
        pitch=pitch
    )

def get_voice_selection_params(language_code="en-US", name=None, ssml_gender=None):
    """Returns a configured VoiceSelectionParams object."""
    params = {"language_code": language_code}
    if name: params["name"] = name
    if ssml_gender: params["ssml_gender"] = getattr(texttospeech.SsmlVoiceGender, ssml_gender.upper())
    return texttospeech.VoiceSelectionParams(**params)

from typing import Dict, Any

def create_synthesis_input(text: str = None, ssml: str = None) -> Dict[str, Any]:
    """Creates a dictionary for synthesis input."""
    if text:
        return {"text": text}
    elif ssml:
        return {"ssml": ssml}
    else:
        raise ValueError("Either 'text' or 'ssml' must be provided.")

def parse_synthesis_response(response) -> Dict[str, Any]:
    """Parses the Text-to-Speech synthesis response."""
    return {"audio_bytes": response.audio_content, "content_type": "audio/mpeg"}

def normalize_voice_selection_params(language_code: str, voice_name: str = None) -> Dict[str, Any]:
    """Normalizes voice selection parameters."""
    params = {"language_code": language_code}
    if voice_name: params["name"] = voice_name
    return params

def normalize_audio_config(audio_encoding: str = "MP3", speaking_rate: float = 1.0, pitch: float = 0.0) -> Dict[str, Any]:
    """Normalizes audio configuration parameters."""
    return {"audio_encoding": audio_encoding, "speaking_rate": speaking_rate, "pitch": pitch}

from google.cloud import aiplatform
import os

def embed_script(text, project_id=None, location="us-central1"):
    if project_id is None:
        # Attempt to get project ID from environment variable or gcloud config
        project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
        if not project_id:
            raise ValueError("Google Cloud project ID not found. Please set GOOGLE_CLOUD_PROJECT environment variable or pass it directly.")

    aiplatform.init(project=project_id, location=location)

    # Use the pre-trained text embedding model
    # You might need to specify a more precise model_id depending on the available models
    # For example, "text-embedding-004" or similar if available and suitable.
    # For this example, I'll use a generic reference as specific model IDs can change.
    # In a real scenario, you'd confirm the exact model ID from Vertex AI documentation.
    model = aiplatform.TextEmbeddingModel.from_pretrained("textembedding-gecko@003") # A common, general-purpose embedding model

    embeddings = model.get_embeddings([text])

    # The embeddings object is a list of Embedding objects, each with values (list of floats)
    if embeddings and embeddings[0].values:
        return {"embedding": embeddings[0].values}
    else:
        return {"embedding": []}
